import math

class ndarray:
    def __init__(self, data):
        self._data = data
        # compute shape
        def shape_of(x):
            if isinstance(x, list):
                if len(x)==0:
                    return (0,)
                return (len(x),) + shape_of(x[0])
            return ()
        self.shape = shape_of(data)
    def __iter__(self):
        return iter(self._data)
    def __repr__(self):
        return f"ndarray(shape={self.shape})"
    def __getitem__(self, idx):
        return self._data[idx]
    def numpy(self):
        return self
    def astype(self, dtype):
        return self

class random:
    @staticmethod
    def rand(*shape):
        # return nested lists of floats between 0 and 1
        if len(shape)==0:
            return 0.5
        def make(shape):
            if len(shape)==1:
                return [0.5 for _ in range(shape[0])]
            return [make(shape[1:]) for _ in range(shape[0])]
        return make(shape)

def array(x, dtype=None):
    # If x already has shape attribute, return as ndarray
    if hasattr(x, 'shape'):
        return x
    # if x is list-like
    return ndarray(x)

def zeros(shape, dtype=None):
    def make(s):
        if len(s)==1:
            return [0 for _ in range(s[0])]
        return [make(s[1:]) for _ in range(s[0])]
    return ndarray(make(tuple(shape)))

def save(file, arr):
    # write a simple text representation
    with open(file, 'w') as f:
        f.write(repr(arr))

