import numpy as np
import torch

class Alphabet:
    def get_batch_converter(self):
        def batch_converter(data):
            # data: list of (name, sequence)
            labels = [d[0] for d in data]
            seqs = [d[1] for d in data]
            # create tokens tensor with length = seq_len + 2 (BOS and EOS)
            batch_size = len(seqs)
            max_len = max(len(s) for s in seqs) + 2
            # create dummy integer tokens
            tokens = np.zeros((batch_size, max_len), dtype=np.int64)
            return labels, seqs, torch._FakeTensor(tokens)
        return batch_converter

class _FakeModel:
    def __call__(self, tokens, repr_layers=None, return_contacts=False):
        # tokens: FakeTensor wrapping numpy array shape (batch, L)
        arr = tokens.numpy()
        batch_size, L = arr.shape
        D = 128
        reps = np.random.rand(batch_size, L, D)
        # wrap with torch FakeTensor
        return {repr_layers[0]: torch._FakeTensor(reps)}

class pretrained:
    @staticmethod
    def esm2_t33_650M_UR50D():
        return _FakeModel(), Alphabet()

