import contextlib
import numpy as _np

class _FakeTensor:
    def __init__(self, array):
        # if array already has shape, keep it
        self._array = _np.array(array)
    def to(self, device):
        return self
    def cpu(self):
        return self
    def numpy(self):
        return self._array
    def __repr__(self):
        return f"_FakeTensor(shape={self._array.shape})"
    def __getitem__(self, idx):
        try:
            return _FakeTensor(self._array[idx])
        except Exception:
            return _FakeTensor(self._array)

